import random
from collections import deque
from func import min_operations_to_rearrange as f

def indep(n, s, t):
    if sorted(s) != sorted(t): return -1
    start, target = s+'..', t+'..'
    if start == target: return 0
    # bidirectional BFS, different code path
    def nbrs(cur):
        e = cur.index('.'); res = []
        for i in range(n+1):
            if cur[i] != '.' and cur[i+1] != '.':
                nx = list(cur)
                nx[e], nx[e+1], nx[i], nx[i+1] = cur[i], cur[i+1], '.', '.'
                res.append(''.join(nx))
        return res
    dA, dB = {start:0}, {target:0}
    qa, qb = deque([start]), deque([target])
    while qa and qb:
        if len(dA) <= len(dB):
            cur = qa.popleft(); side = 0
        else:
            cur = qb.popleft(); side = 1
        dd = (dA if side==0 else dB)[cur]
        for nb in nbrs(cur):
            do, db = (dA, dB) if side==0 else (dB, dA)
            if nb not in do:
                do[nb] = dd+1; (qa if side==0 else qb).append(nb)
            if nb in db:
                return do[nb] + db[nb]
    return -1

